   gsize i;
   guint v = 0;

   if (length < 1 || length > 4)
     return FALSE;

   for (i = 0; i < length; i++)
     {
       const gchar c = text[i];
       if (c < '0' || c > '9')
         return FALSE;
       v = v * 10 + (c - '0');
     }

