 {
   GDateTime *dt;

   if (ordinal_day < 1 || ordinal_day > (GREGORIAN_LEAP (year) ? 366 : 365))
     return NULL;

   dt = g_date_time_new (tz, year, 1, 1, hour, minute, seconds);
   if (dt == NULL)
     return NULL;
   dt->days += ordinal_day - 1;

   return dt;
